SELECT count(*) AS total,        count(*) FILTER (WHERE s.bid IS NOT NULL                           AND s.ask IS NOT NULL) AS two_sided,        count(*) FILTER (WHERE s.market_state_id IS NULL                            OR s.readable IS NOT TRUE)            AS unreadable,        count(*) FILTER (WHERE s.readable IS TRUE                           AND (s.bid IS NULL) <> (s.ask IS NULL))            AS one_sided   FROM bettor_opportunities o   LEFT JOIN shadow_market_states s          ON s.market_state_id = o.market_state_id;
